// Partner settings affect only how outbound provider links are rendered, never which plans or courses appear.
const Outbound=createRequire(import.meta.url)('../dist/outbound.js');

const root = resolve(import.meta.dirname, '..'), dist = resolve(root, 'dist');
const originValue = process.env.DEGREEPATH_PUBLIC_ORIGIN || 'https://degreesteps.com';
const parsedOrigin = new URL(originValue);
assert(['https:', 'http:'].includes(parsedOrigin.protocol) && !parsedOrigin.username && !parsedOrigin.password && parsedOrigin.pathname === '/', 'Set DEGREEPATH_PUBLIC_ORIGIN to the complete public origin, without a path.');
const origin = parsedOrigin.origin;
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const slug = value => String(value).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const json = value => JSON.stringify(value).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
const safeURL = value => {try {const u = new URL(value); return ['https:','http:'].includes(u.protocol) && !u.username && !u.password ? u.href : '';} catch {return '';}};
const partnerSettings=Outbound.configure(JSON.parse(await readFile(resolve(root,'content/monetization/partners.json'),'utf8')));
await writeFile(resolve(dist,'data/partners.json'),JSON.stringify(partnerSettings,null,2)+'\n');
// School contact requests and the paid Plan review (both off by default). The Worker reads this file for the
// school allowlist and the offer; the build flags below only add their disclosure copy and the sitemap entry.
// Turning a feature on needs the same flag at run time (Worker variable) and at build time; the Deploy workflow passes both (see docs/beta-deploy-checklist.md).
const schoolInquiriesBuild=process.env.SCHOOL_INQUIRIES_ENABLED==='1',planReviewBuild=process.env.PLAN_REVIEW_ENABLED==='1';
const leadSettings=normalizeLeadSettings({schools:JSON.parse(await readFile(resolve(root,'content/monetization/schools.json'),'utf8')).schools,planReview:JSON.parse(await readFile(resolve(root,'content/monetization/plan-review.json'),'utf8'))});
await writeFile(resolve(dist,'data/lead-settings.json'),JSON.stringify(leadSettings,null,2)+'\n');
const reviewPrice=new Intl.NumberFormat('en-US',{style:'currency',currency:leadSettings.planReview.currency,maximumFractionDigits:0,minimumFractionDigits:0}).format(leadSettings.planReview.price);
const readinessRegistry=JSON.parse(await readFile(resolve(dist,'data/curriculum-registry.json'),'utf8'));
const pathwayQuality=JSON.parse(await readFile(resolve(dist,'data/pathway-quality-report.json'),'utf8'));
const publishedModelIds=new Set((pathwayQuality.programs||[]).filter(program=>program.publication?.ready===true).map(program=>program.modelId));
const availableSchoolCounts=new Map();for(const entry of readinessRegistry.models||[])if(entry.readyTemplate===true&&publishedModelIds.has(entry.id))availableSchoolCounts.set(entry.school,(availableSchoolCounts.get(entry.school)||0)+1);
const pathways = JSON.parse(await readFile(resolve(dist,'data/pathways.json'),'utf8'));
const creditCatalog = JSON.parse(await readFile(resolve(dist,'data/credit-sources.json'),'utf8'));
const indexedProviderNames=new Set([...JSON.parse(await readFile(resolve(dist,'data/course-catalog.json'),'utf8')).courses,...JSON.parse(await readFile(resolve(dist,'data/curriculum-course-index.json'),'utf8')).courses].flatMap(course=>[course.provider,course.providerId]).filter(Boolean).map(value=>String(value).trim().toLowerCase()));
function providerAction(source){const action=sourceAction(source),provider=new URL(action.href,origin).searchParams.get('provider');return provider&&!indexedProviderNames.has(provider.trim().toLowerCase())?{label:'Build my degree plan',href:'/portal.html',description:'Start with your degree to see the course options available in your plan.'}:action;}
let content;
try {content = JSON.parse(await readFile(resolve(root,'content/public-content.json'),'utf8'));} catch {content = {articles:[]};}
const articles = content.articles || [], articleBySlug = new Map(articles.map(a => [a.slug,a]));
assert.equal(articleBySlug.size, articles.length, 'Editorial slugs must be unique.');
const pathFor = article => '/' + (article.type === 'guide' ? 'guides' : 'blog') + '/' + article.slug + '/';
const guides = articles.filter(a => a.type === 'guide'), posts = articles.filter(a => a.type !== 'guide');
const costData=JSON.parse(await readFile(resolve(dist,'data/cost-comparisons.json'),'utf8'));
const exampleProgram=JSON.parse(await readFile(resolve(dist,'data/liberty.json'),'utf8'));
const exampleBaselines=JSON.parse(await readFile(resolve(dist,'data/baseline-index.json'),'utf8'));
const example=buildHomeExample({program:exampleProgram,baseline:Object.values(exampleBaselines.baselines).find(row=>row.modelId===exampleProgram.id),Planner:createRequire(import.meta.url)(resolve(dist,'planner.js'))});
// One description of the plan library's scope, from the same index the finder reads: every finder plan, its schools,
// and how many are reviewed versus still awaiting school confirmation.
const planScope=(index=>{const plans=Object.values(index.plans);return {total:plans.length,schools:new Set(plans.map(plan=>plan.route.school)).size,reviewed:plans.filter(plan=>plan.start?.tier==='reviewed').length};})(JSON.parse(await readFile(resolve(dist,'data/plan-course-index.json'),'utf8')));
const homeEstimate=buildHomeEstimate({example,program:exampleProgram,baseline:Object.values(exampleBaselines.baselines).find(row=>row.modelId===exampleProgram.id),Planner:createRequire(import.meta.url)(resolve(dist,'planner.js')),Estimate:createRequire(import.meta.url)(resolve(dist,'plan-estimate-engine.js')),rates:JSON.parse(await readFile(resolve(dist,'data/plan-estimate-rates.json'),'utf8')),indexEntry:JSON.parse(await readFile(resolve(dist,'data/plan-library-index.json'),'utf8')).plans[exampleProgram.id]});
const publicPlans=await loadPublicPlans(dist);
await removeObsoletePreviews(dist,publicPlans);
const pages = [];
const brand = '<a class="site-brand ds-wordmark" href="/" aria-label="DegreeSteps home"><span>Degree</span><span class="ds-wordmark-steps">Steps</span></a>';
const arrow = '';
const cta = (label='Build my plan',href='/portal.html') => '<a class="site-button" href="'+esc(href)+'">'+esc(label)+'</a>';
const sourceLinks = sources => '<ul class="source-list">'+[...new Map((sources || []).filter(s => safeURL(s.url)).map(s => [s.url,s])).values()].map(s => '<li><a href="'+esc(safeURL(s.url))+'" target="_blank" rel="noopener">'+esc(s.title || s.url)+arrow+'</a>'+(s.checkedOn ? '<small>Checked '+esc(s.checkedOn)+'</small>' : '')+'</li>').join('')+'</ul>';
const list = values => '<ul class="plain-list">'+(values || []).map(value => '<li>'+esc(value)+'</li>').join('')+'</ul>';
const paragraph = value => '<p>'+esc(value)+'</p>';
const reviewed = value => /^\d{4}-\d{2}-\d{2}$/.test(value || '') ? value : null;
const eyebrow = value => '<p class="page-context">'+esc(value)+'</p>';
function header(current) {
  return '<header class="public-header"><div class="header-inner">'+brand+'<details class="site-menu" open><summary aria-label="Main navigation menu">Menu <span aria-hidden="true">☰</span></summary><nav aria-label="Main navigation"><a href="/how-it-works/"'+(current==='how'?' aria-current="page"':'')+'>How it works</a><a href="/degree-plans/"'+(current==='plans'?' aria-current="page"':'')+'>Degree plans</a><a href="/resources/"'+(current==='resources'?' aria-current="page"':'')+'>Resources</a><a class="nav-signin" href="/account.html">Sign in</a><a class="site-button nav-cta" href="/portal.html">Build my plan</a></nav></details></div></header>';
}
function footer() {
  return '<footer class="public-footer"><div class="footer-top"><div>'+brand+'<p>A clearer path to your degree. Built around your life.</p></div><div><h2>Start your path</h2><a href="/portal.html">Build a degree plan</a><a href="/degree-plans/">Preview researched plans</a><a href="/campuses.html">Find a campus</a><a href="/how-it-works/">How it works</a><a href="/compare/">Compare college costs</a><a href="/account.html">My account</a><a href="/about/">Our story</a></div><div><h2>Learn & compare</h2><a href="/courses.html">Browse courses</a><a href="/guides/">Student guides</a><a href="/schools/">School resources</a><a href="/credit-sources/">Credit sources</a><a href="/transfer/">Transfer courses</a><a href="/blog/">The DegreeSteps journal</a></div><div><h2>Get oriented</h2><a href="/faq/">Common questions</a><a href="/community.html">Community</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/why-its-free/">Why DegreeSteps is free</a></div></div><div class="footer-bottom"><p>DegreeSteps is a planning resource. Your school makes the final decisions about credit and degree requirements.</p><p>© '+new Date().getUTCFullYear()+' DegreeSteps</p></div></footer>';
}
function breadcrumb(items) {
  return '<nav class="breadcrumbs" aria-label="Breadcrumb"><ol><li><a href="/">Home</a></li>'+items.map((item,i) => '<li>'+(i === items.length - 1 ? '<span aria-current="page">'+esc(item.name)+'</span>' : '<a href="'+esc(item.path)+'">'+esc(item.name)+'</a>')+'</li>').join('')+'</ol></nav>';
}
function layout({path,title,description,body,section='',crumbs=[],schema=[],date,kind='website'}) {
  const canonical = origin + path;
  const costAssets=['/','/compare/'].includes(path)?'<link rel="stylesheet" href="/cost-comparison.css"><script src="/cost-engine.js" defer></script><script src="/cost-comparison.js" defer></script>':'';
  const socialImage = '<meta property="og:image" content="'+origin+'/images/degreesteps-social.png"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="DegreeSteps: your degree, your pace; a faster, more affordable path to graduation."><meta name="twitter:image" content="'+origin+'/images/degreesteps-social.png"><meta name="twitter:image:alt" content="DegreeSteps: your degree, your pace; a faster, more affordable path to graduation.">';
  const estimateAssets=path.startsWith('/degree-plans/')?'<link rel="stylesheet" href="/plan-estimate.css">':'';
  const previewAssets=path.startsWith('/degree-plans/')||path.startsWith('/schools/')||kind==='article'?'<link rel="stylesheet" href="/public-plan-preview.css"><script src="/public-plan-preview.js" defer></script>':'';
  const libraryAssets=path==='/degree-plans/'?'<script src="/plan-library.js" defer></script>':path==='/plan-review/'?'<link rel="stylesheet" href="/leads.css">':'';
  const growthContext=path==='/'?'home':path.startsWith('/transfer/')?'transfer':path.startsWith('/degree-plans/')?'degree-plan':path.startsWith('/credit-sources/')?'provider':path.startsWith('/schools/')?'school':kind==='article'?'article':'home';
  const structured = [...schema];
  if (crumbs.length) structured.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{name:'Home',item:origin+'/'},...crumbs.map(c=>({name:c.name,item:origin+c.path}))].map((c,i)=>({'@type':'ListItem',position:i+1,...c}))});
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#4054f4"><title>'+(path==='/'?'DegreeSteps | College planning, credits &amp; costs':esc(title)+' | DegreeSteps')+'</title><meta name="description" content="'+esc(description)+'"><link rel="canonical" href="'+esc(canonical)+'"><meta property="og:type" content="'+kind+'"><meta property="og:site_name" content="DegreeSteps"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(description)+'"><meta property="og:url" content="'+esc(canonical)+'"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'+esc(title)+'"><meta name="twitter:description" content="'+esc(description)+'">'+socialImage+'<link rel="stylesheet" href="/site.css">'+(path==='/'?'<link rel="stylesheet" href="/home.css"><script src="/home-steps.js" defer></script>':'')+'<script src="/growth-metrics.js" defer></script>'+costAssets+previewAssets+libraryAssets+estimateAssets+'<link rel="stylesheet" href="/brand.css"><link rel="stylesheet" href="/experience.css"><link rel="stylesheet" href="/public-design.css"><link rel="stylesheet" href="/student-resources.css"><script src="/site.js" defer></script><script src="/step-trail.js" defer></script>'+structured.map(value=>'<script type="application/ld+json">'+json(value)+'</script>').join('')+'</head><body data-growth-context="'+growthContext+'" class="ds-experience ds-public-page public-page'+(path==='/'?' home-public':'')+'"><a class="site-skip" href="#main">Skip to content</a>'+header(section)+'<main id="main"'+(path==='/'?' class="home-page"':path==='/compare/'?' class="cost-page"':'')+'>'+(crumbs.length?'<div class="site-container">'+breadcrumb(crumbs)+'</div>':'')+body+'</main>'+footer()+'</body></html>';
}
async function page(options) {
  const file = options.path === '/' ? 'index.html' : options.path.slice(1)+'index.html';
  await mkdir(resolve(dist,file,'..'),{recursive:true});
  await writeFile(resolve(dist,file),layout(options));
  pages.push({path:options.path,date:reviewed(options.date)});
}
function articleCard(article) {
  const category=article.category || (article.type==='guide'?'Student guide':'Planning journal');
  return '<article class="resource-card"><span class="resource-card-tile" aria-hidden="true">'+icon(articleIcon(category))+'</span><div class="resource-card-label">'+esc(category)+' <span>'+esc(article.readMinutes || 5)+' min read</span></div><h3><a href="'+esc(pathFor(article))+'">'+esc(article.title)+'</a></h3><p>'+esc(article.description)+'</p><a class="text-link" href="'+esc(pathFor(article))+'">'+(article.type==='guide'?'Read the guide':'Read the article')+'</a></article>';
}
function featureCard(article,label) {
  const category=article.category || (article.type==='guide'?'Student guide':'Planning journal');
  return '<article class="resource-feature"><div class="resource-feature-art" aria-hidden="true">'+icon(articleIcon(category),'ds-icon resource-feature-icon')+'</div><div class="resource-feature-copy"><p class="ds-step-kicker">'+esc(label)+'</p><div class="resource-card-label">'+esc(category)+' <span>'+esc(article.readMinutes || 5)+' min read</span></div><h2><a href="'+esc(pathFor(article))+'">'+esc(article.title)+'</a></h2><p>'+esc(article.description)+'</p><a class="site-button" href="'+esc(pathFor(article))+'">'+(article.type==='guide'?'Read the guide':'Read the article')+'</a></div></article>';
}
function readingPath(steps) {
  return '<section class="reading-path" aria-labelledby="reading-path-title"><div class="site-container"><div class="reading-path-head"><p class="ds-step-kicker">Start here</p><h2 id="reading-path-title">New to transfer credit? Read these in order.</h2><p>'+steps.length+' short guides, about '+steps.reduce((sum,article)=>sum+(article.readMinutes||5),0)+' minutes in all. Each one builds on the last.</p></div><ol class="reading-path-steps">'+steps.map((article,index)=>'<li><span class="reading-step-node" aria-hidden="true">'+(index+1)+'</span><p class="reading-step-label">Step '+(index+1)+' · '+esc(article.category||'Guide')+'</p><h3><a href="'+esc(pathFor(article))+'">'+esc(article.title)+'</a></h3><p>'+esc(article.readMinutes||5)+' min read</p></li>').join('')+'</ol></div></section>';
}
function sectionHeader(kicker,title,description,href,label) {return '<div class="section-heading"><div><h2>'+esc(title)+'</h2>'+(description?'<p>'+esc(description)+'</p>':'')+'</div>'+(href?'<a class="text-link" href="'+href+'">'+esc(label)+'</a>':'')+'</div>';}
function callout(title='Ready to see your courses?',description='Choose your goal. See a degree plan with eligible outside courses and a clear next step.') {
  return '<section class="site-container final-cta"><div><p class="ds-step-kicker">Your next step</p><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p></div><div>'+cta('Start a free degree plan')+'<p>No account needed to explore.</p></div></section>';
}

const faq = [
  ['What does DegreeSteps help me do?','DegreeSteps helps you build a starting degree plan around your goals, preferred school, existing learning, and priorities. It brings outside-credit options, degree requirements, open questions, and next steps into one place.'],
  ['Can I really take courses outside my university?','Many schools consider credit from other colleges, approved exams, military learning, and courses with ACE or NCCRS recommendations. Acceptance and degree placement depend on the exact school, program, course, dates, and your individual evaluation.'],
  ['Does an ACE recommendation guarantee transfer credit?','No. ACE makes credit recommendations; it does not accredit a provider as a college or require schools to accept a course. The receiving school decides whether the learning is accepted and which degree requirements it satisfies.'],
  ['Can this work for an on-campus degree?','It can. A residential program may allow outside learning before enrollment or while enrolled, subject to its own policies. Campus attendance, major requirements, institutional-credit minimums, and course availability still need to be planned.'],
  ['Do I need transcripts to get started?','No. You can build a clearly provisional starting plan and add original learning records later. DegreeSteps never guesses earned credits from a rough estimate. An official evaluation is needed to establish your individual awards.'],
  ['Can DegreeSteps tell me the cheapest or fastest degree?','Your priority shapes the suggested path. A reliable final price and finish date also require current school fees, approved credits, your pace, prerequisites, and actual course schedules. Missing information remains visible rather than being treated as zero cost or instant completion.'],
  ['Which degrees can I build a plan for?','The degree picker shows available course-by-course templates. You can also build a private plan or research a degree from its official link. School-resource pages cover a wider selection of colleges; those overviews do not imply that every program has a complete transfer plan.'],
  ['How do community-verified transfers work?','Student reports add real-world evidence for a particular placement and catalog. Verification uses evidence rules rather than popularity alone. Community feedback helps identify a promising match or a problem; it cannot establish your own school-approved credit award.'],
  ['Is DegreeSteps free?','Yes. DegreeSteps is free to use: exploring plans, building your plan and saving it to your free account cost nothing. Courses, tuition and provider fees are separate.',['See why DegreeSteps is free','/why-its-free/']],
  ['Will a degree path qualify me for a licensed profession?','Teaching, law, aviation, and health professions can require approved preparation, clinical or classroom work, examinations, and jurisdiction-specific licensing. DegreeSteps keeps those checks separate from simply completing academic credits.']
];
const faqMarkup = items => '<div class="faq-list">'+items.map(([q,a,link])=>'<details><summary>'+esc(q)+'</summary><p>'+esc(a)+(link?' <a href="'+esc(link[1])+'">'+esc(link[0])+'</a>':'')+'</p></details>').join('')+'</div>';

await page({path:'/',title:'College planning, credits & costs',description:'Explore affordable courses, potential transfer credits, and college options. Build a degree plan around your goals, time, and budget with DegreeSteps.',body:renderHome({cta,articleCard,guides,costSection:renderCostWidget(costData),example,estimate:homeEstimate}),schema:[{'@context':'https://schema.org','@type':'Organization',name:'DegreeSteps',url:origin+'/',description:'DegreeSteps helps students explore affordable courses, potential transfer credits, and flexible college plans.'},{'@context':'https://schema.org','@type':'WebSite',name:'DegreeSteps',url:origin+'/'}]});

