await page({path:'/credit-sources/',section:'resources',title:'Transfer-credit sources: courses, exams, and prior learning',description:'Compare Sophia, Study.com, StraighterLine, CLEP, Saylor, military learning, and other credit sources with clear transfer and assessment checks.',date:creditCatalog.checkedOn,crumbs:[{name:'Credit sources',path:'/credit-sources/'}],body:'<section class="site-container page-intro ds-rail-intro source-intro"><div class="ds-rail-copy">'+eyebrow('More ways to build your path')+'<h1>Explore credit sources. Find what fits.</h1><p class="page-lede">Self-paced courses, exams, credentials, and training can serve different needs. Start with your school’s rules, then compare the experience and full cost.</p><p class="intro-note">An ACE or NCCRS recommendation is different from college accreditation. A listing here does not establish an approved degree placement.</p><label class="resource-search"><span>Find a credit source or method</span><input type="search" data-resource-search placeholder="Try StraighterLine, exams, or military" autocomplete="off"></label><p data-resource-count class="search-count" role="status" aria-live="polite"></p></div>'+sourceJump+'</section>'+sourceGroups.map(sourceGroupSection).join('')+callout()});
